CREATE OR REPLACE FUNCTION stock_funding.move(o uuid, s uuid, account_id uuid, c text, d numeric, k text, adv uuid, t timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE req uuid:=nullif(current_setting('funding_canonical.request',true),'')::uuid;

BEGIN

 IF req IS NULL OR NOT isfinite(t) THEN RAISE EXCEPTION 'CANONICAL_GATEWAY_REQUIRED'; END IF;

 PERFORM funding_control.post(account_id,adv,req,k,abs(d));

 PERFORM funding_canonical.custody_event(adv,k,req);

END $function$

CREATE OR REPLACE FUNCTION stock_funding.command(p_org uuid, p_store uuid, p_request uuid, p_advance uuid, p_action text, p_body jsonb, p_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE v_actor uuid; v_old stock_funding.advances%ROWTYPE; v_cached stock_funding.requests%ROWTYPE;

 v_envelope jsonb; v_result jsonb; v_ctx jsonb; v_amount numeric:=0; v_receipt uuid; v_account uuid; v_time timestamptz; v_previous text;

BEGIN

 v_actor:=stock_funding.actor();

 IF v_actor IS NULL OR p_org IS NULL OR p_store IS NULL OR p_request IS NULL OR p_advance IS NULL OR p_body IS NULL OR jsonb_typeof(p_body)<>'object' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 IF p_action IS NULL OR p_action NOT IN ('CREATE','APPROVE','FUND','RECEIPT','RETURN','CANCEL','REVERSE') OR stock_funding.allowed(v_actor,p_org,p_store,p_action) IS NOT TRUE THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 -- Fixed order: organization/request lock, advance row, currency config, account/shift or receipt.

 PERFORM pg_advisory_xact_lock(hashtextextended(p_org::text||p_request::text,0));

 v_envelope:=jsonb_build_object('store',p_store,'advance',p_advance,'action',p_action,'body',p_body,'revision',p_revision);

 SELECT * INTO v_cached FROM stock_funding.requests WHERE organization_id=p_org AND request_id=p_request;

 IF FOUND THEN

  IF v_cached.actor_id<>v_actor OR v_cached.envelope<>v_envelope THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;

  RETURN v_cached.result;

 END IF;

 v_time:=(p_body->>'occurredAt')::timestamptz;

 IF v_time IS NULL OR NOT isfinite(v_time) THEN RAISE EXCEPTION 'DATE_REQUIRED'; END IF;

 IF p_action='CREATE' THEN

  v_ctx:=stock_funding.currency_context(p_org);

  IF v_ctx IS NULL OR (v_ctx->>'revision')::integer IS NULL OR (v_ctx->>'minorUnits')::integer IS NULL THEN RAISE EXCEPTION 'ACCOUNTING_CURRENCY_UNCONFIRMED'; END IF;

  IF p_body->>'currency' IS DISTINCT FROM v_ctx->>'currency' THEN RAISE EXCEPTION 'CROSS_CURRENCY_BLOCKED'; END IF;

  v_amount:=(p_body->>'amount')::numeric;

  IF v_amount IS NULL OR v_amount<=0 OR v_amount>=1e24 OR v_amount<>round(v_amount,(v_ctx->>'minorUnits')::integer) THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;

  PERFORM stock_funding.validate_responsible(p_org,p_store,(p_body->>'responsibleId')::uuid);

  INSERT INTO stock_funding.advances(id,organization_id,store_id,currency,currency_revision,minor_units,amount,source_account,responsible_id,created_by,purpose,supplier_reference,occurred_at,expected_at,status)

  VALUES(p_advance,p_org,p_store,p_body->>'currency',(v_ctx->>'revision')::integer,(v_ctx->>'minorUnits')::integer,v_amount,(p_body->>'sourceAccountId')::uuid,(p_body->>'responsibleId')::uuid,v_actor,p_body->>'purpose',p_body->>'supplierReference',v_time,(p_body->>'expectedAt')::timestamptz,'DRAFT');

 ELSE

  SELECT * INTO v_old FROM stock_funding.advances WHERE id=p_advance FOR UPDATE;

  IF NOT FOUND OR v_old.organization_id<>p_org OR v_old.store_id<>p_store THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  IF p_revision IS DISTINCT FROM v_old.revision THEN RAISE EXCEPTION 'STALE_REVISION'; END IF;

  v_previous:=v_old.status;

  IF p_action='APPROVE' THEN

   IF v_old.status<>'DRAFT' THEN RAISE EXCEPTION 'INVALID_TRANSITION'; END IF;

   UPDATE stock_funding.advances SET status='APPROVED' WHERE id=p_advance;

  ELSIF p_action='CANCEL' THEN

   IF v_old.status NOT IN ('DRAFT','APPROVED') THEN RAISE EXCEPTION 'REVERSAL_REQUIRED'; END IF;

   UPDATE stock_funding.advances SET status='CANCELLED' WHERE id=p_advance;

  ELSE

   v_ctx:=stock_funding.currency_context(p_org);

   IF v_ctx IS NULL OR (v_ctx->>'currency') IS DISTINCT FROM v_old.currency OR (v_ctx->>'revision')::integer IS DISTINCT FROM v_old.currency_revision THEN RAISE EXCEPTION 'CURRENCY_CONTEXT_CHANGED'; END IF;

   IF p_body->>'currency' IS DISTINCT FROM v_old.currency THEN RAISE EXCEPTION 'CROSS_CURRENCY_BLOCKED'; END IF;

   IF p_action='FUND' THEN

    IF v_old.status<>'APPROVED' THEN RAISE EXCEPTION 'INVALID_TRANSITION'; END IF;

    v_amount:=v_old.amount;v_account:=v_old.source_account;

    PERFORM stock_funding.move(p_org,p_store,v_account,v_old.currency,-v_amount,'FUND',p_advance,v_time);

    UPDATE stock_funding.advances SET status='FUNDED' WHERE id=p_advance;

   ELSIF p_action IN ('RETURN','RECEIPT') THEN

    IF v_old.status NOT IN ('FUNDED','PARTIALLY_RECONCILED') THEN RAISE EXCEPTION 'INVALID_TRANSITION'; END IF;

    v_amount:=(p_body->>'amount')::numeric;

    IF v_amount IS NULL OR v_amount<=0 OR v_amount>v_old.amount-v_old.spent-v_old.returned OR v_amount<>round(v_amount,v_old.minor_units) THEN RAISE EXCEPTION 'OVER_RECONCILIATION'; END IF;

    IF p_action='RETURN' THEN

     PERFORM stock_funding.validate_responsible(p_org,p_store,(p_body->>'returningPersonId')::uuid);

     v_account:=(p_body->>'destinationAccountId')::uuid;

     IF v_account IS NULL THEN RAISE EXCEPTION 'ACCOUNT_REQUIRED'; END IF;

     PERFORM stock_funding.move(p_org,p_store,v_account,v_old.currency,v_amount,'RETURN',p_advance,v_time);

     UPDATE stock_funding.advances SET returned=returned+v_amount WHERE id=p_advance;

    ELSE

     v_receipt:=(p_body->>'receiptId')::uuid;

     IF v_receipt IS NULL THEN RAISE EXCEPTION 'RECEIPT_REQUIRED'; END IF;

     PERFORM stock_funding.consume_receipt(p_org,p_store,v_receipt,v_amount,v_old.currency,p_advance);

     INSERT INTO stock_funding.receipt_links(receipt_id,advance_id,amount) VALUES(v_receipt,p_advance,v_amount);

     UPDATE stock_funding.advances SET spent=spent+v_amount WHERE id=p_advance;

    END IF;

    UPDATE stock_funding.advances SET status=CASE WHEN spent+returned=amount THEN 'RECONCILED' ELSE 'PARTIALLY_RECONCILED' END WHERE id=p_advance;

   ELSIF p_action='REVERSE' THEN

    IF v_old.status<>'FUNDED' OR v_old.spent<>0 OR v_old.returned<>0 OR length(trim(coalesce(p_body->>'reason','')))=0 THEN RAISE EXCEPTION 'CONTROLLED_REVERSAL_REQUIRED'; END IF;

    v_amount:=v_old.amount;v_account:=v_old.source_account;

    PERFORM stock_funding.move(p_org,p_store,v_account,v_old.currency,v_amount,'REVERSE',p_advance,v_time);

    UPDATE stock_funding.advances SET status='REVERSED',returned=amount WHERE id=p_advance;

   END IF;

  END IF;

  UPDATE stock_funding.advances SET revision=revision+1 WHERE id=p_advance;

 END IF;

 SELECT jsonb_build_object('id',id,'status',status,'revision',revision,'currency',currency,'amount',amount::text,'spent',spent::text,'returned',returned::text,'outstanding',CASE WHEN status IN ('DRAFT','APPROVED','CANCELLED','REVERSED') THEN '0' ELSE (amount-spent-returned)::text END)

 INTO v_result FROM stock_funding.advances WHERE id=p_advance;

 INSERT INTO stock_funding.events(advance_id,request_id,actor_id,action,amount,account_id,receipt_id,occurred_at,previous_status,next_status,reason,returning_person_id)

 VALUES(p_advance,p_request,v_actor,p_action,v_amount,v_account,v_receipt,v_time,v_previous,v_result->>'status',p_body->>'reason',CASE WHEN p_action='RETURN' THEN (p_body->>'returningPersonId')::uuid END);

 INSERT INTO stock_funding.requests VALUES(p_org,p_request,v_actor,v_envelope,v_result);

 RETURN v_result;

END $function$

CREATE OR REPLACE FUNCTION funding_control.configure(p_account uuid, p_op text, p_body jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE a uuid:=stock_funding.actor();ac funding_control.accounts%ROWTYPE;ctx jsonb;role text;target uuid;

BEGIN

 IF p_op='CREATE_ACCOUNT' THEN

  IF funding_control.member_role(a,(p_body->>'organizationId')::uuid,(p_body->>'storeId')::uuid) IS DISTINCT FROM 'owner' THEN RAISE EXCEPTION 'OWNER_REQUIRED'; END IF;

  ctx:=stock_funding.currency_context((p_body->>'organizationId')::uuid);

  IF ctx IS NULL OR ctx->>'currency' IS DISTINCT FROM p_body->>'currency' THEN RAISE EXCEPTION 'CURRENCY_CONTEXT_CHANGED'; END IF;

  IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=p_body->>'timezone') THEN RAISE EXCEPTION 'INVALID_TIMEZONE'; END IF;

  IF (p_body->>'opening')::numeric<>round((p_body->>'opening')::numeric,(ctx->>'minorUnits')::integer) THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;

  INSERT INTO funding_control.accounts(id,org,store,kind,currency,opening,confirmed_by,evidence,timezone) VALUES(p_account,(p_body->>'organizationId')::uuid,(p_body->>'storeId')::uuid,p_body->>'kind',p_body->>'currency',(p_body->>'opening')::numeric,a,p_body->>'evidence',p_body->>'timezone');

 ELSE

  SELECT * INTO ac FROM funding_control.accounts WHERE id=p_account FOR UPDATE;

  IF NOT FOUND OR funding_control.member_role(a,ac.org,ac.store) IS DISTINCT FROM 'owner' THEN RAISE EXCEPTION 'OWNER_REQUIRED'; END IF;

  target:=(p_body->>'actorId')::uuid;

  IF p_op IN ('GRANT','REVOKE','AUTO_POLICY') AND funding_control.member_role(target,ac.org,ac.store) IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  IF p_op='GRANT' THEN

   INSERT INTO funding_control.permissions VALUES(ac.org,ac.store,ac.id,target,p_body->>'operation',a) ON CONFLICT DO NOTHING;

  ELSIF p_op='REVOKE' THEN DELETE FROM funding_control.permissions WHERE account=ac.id AND actor=target AND operation=p_body->>'operation';

  ELSIF p_op='AUTO_POLICY' THEN

   IF (p_body->>'perTransaction')::numeric<>round((p_body->>'perTransaction')::numeric,(stock_funding.currency_context(ac.org)->>'minorUnits')::integer) OR (p_body->>'perDay')::numeric<>round((p_body->>'perDay')::numeric,(stock_funding.currency_context(ac.org)->>'minorUnits')::integer) THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;

   INSERT INTO funding_control.auto_policies VALUES(ac.id,target,(p_body->>'enabled')::boolean,(p_body->>'perTransaction')::numeric,(p_body->>'perDay')::numeric,(p_body->>'settleFirst')::boolean,a)

   ON CONFLICT(account,actor) DO UPDATE SET enabled=excluded.enabled,per_transaction=excluded.per_transaction,per_day=excluded.per_day,settle_first=excluded.settle_first,configured_by=excluded.configured_by;

  ELSIF p_op='LOCK' THEN UPDATE funding_control.accounts SET locked=true WHERE id=ac.id;

  ELSE RAISE EXCEPTION 'INVALID_CONFIGURATION'; END IF;

 END IF;

 INSERT INTO funding_control.configuration_audit(actor,operation,account,body) VALUES(a,p_op,p_account,p_body);

END $function$

CREATE OR REPLACE FUNCTION funding_control.approve(p_advance uuid, p_revision integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE a uuid:=stock_funding.actor();r stock_funding.advances%ROWTYPE;

BEGIN

 SELECT * INTO r FROM stock_funding.advances WHERE id=p_advance FOR UPDATE;

 IF NOT FOUND OR NOT funding_control.can(a,r.organization_id,r.store_id,r.source_account,'APPROVE') OR a=r.created_by THEN RAISE EXCEPTION 'APPROVAL_FORBIDDEN'; END IF;

 IF r.revision IS DISTINCT FROM p_revision OR r.status<>'DRAFT' THEN RAISE EXCEPTION 'STALE_REVISION'; END IF;

 INSERT INTO funding_control.approvals VALUES(r.id,a,r.revision,clock_timestamp());

END $function$

CREATE OR REPLACE FUNCTION funding_control.require_open_shift(a uuid, o uuid, s uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE found_id uuid;count_open integer:=0;shift_row record;

BEGIN

 IF funding_canonical.scope_role(a,o,s) IS DISTINCT FROM 'cashier' THEN RAISE EXCEPTION 'CASHIER_SHIFT_REQUIRED'; END IF;

 FOR shift_row IN SELECT cs.id FROM public.cashier_shifts cs JOIN public.org_memberships m ON m.id=cs.membership_id

  WHERE cs.organization_id=o AND cs.store_id=s AND cs.status='OPEN' AND m.user_id=a AND m.organization_id=o AND m.is_active IS TRUE

  ORDER BY cs.id FOR UPDATE OF cs LOOP count_open:=count_open+1;found_id:=shift_row.id;END LOOP;

 IF count_open<>1 THEN RAISE EXCEPTION 'SHIFT_NOT_OPEN_OR_AMBIGUOUS'; END IF;RETURN found_id;

END $function$

CREATE OR REPLACE FUNCTION funding_control.post(p_account uuid, p_advance uuid, p_request uuid, p_kind text, p_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE a uuid:=stock_funding.actor();ac funding_control.accounts%ROWTYPE;r stock_funding.advances%ROWTYPE;policy funding_control.auto_policies%ROWTYPE;day date;automatic boolean:=false;balance numeric;delta numeric;v_shift uuid;

BEGIN

 SELECT * INTO r FROM stock_funding.advances WHERE id=p_advance FOR UPDATE;

 SELECT * INTO ac FROM funding_control.accounts WHERE id=p_account FOR UPDATE;

 IF r.id IS NULL OR ac.id IS NULL OR ac.org<>r.organization_id OR ac.store<>r.store_id OR ac.currency<>r.currency OR ac.locked OR p_kind NOT IN ('FUND','RETURN','REVERSE') OR p_kind IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'ACCOUNT_FORBIDDEN_OR_LOCKED'; END IF;

 IF p_amount IS NULL OR p_amount<=0 OR p_amount>=1e24 OR p_amount<>round(p_amount,r.minor_units) THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;

 IF funding_control.source_ready(ac.id) IS NOT TRUE THEN RAISE EXCEPTION 'SOURCE_CONTRACT_NOT_BOUND'; END IF;

 IF NOT funding_control.can(a,ac.org,ac.store,ac.id,CASE WHEN p_kind='RETURN' THEN 'RETURN' ELSE 'RELEASE' END) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 IF ac.kind='CASH' THEN v_shift:=funding_control.require_open_shift(a,ac.org,ac.store); IF v_shift IS NULL THEN RAISE EXCEPTION 'SHIFT_NOT_OPEN'; END IF; END IF;

 day:=timezone(ac.timezone,clock_timestamp())::date; -- never client date or language preference

 IF p_kind='FUND' THEN

  IF p_account<>r.source_account OR p_amount<>r.amount OR r.status NOT IN ('DRAFT','APPROVED') THEN RAISE EXCEPTION 'INVALID_TRANSITION'; END IF;

  IF NOT EXISTS(SELECT 1 FROM funding_control.approvals ap WHERE ap.advance=r.id AND ap.approved_by<>r.created_by AND ap.record_revision=r.revision) THEN

   SELECT * INTO policy FROM funding_control.auto_policies WHERE account=ac.id AND actor=a;

   IF NOT FOUND OR NOT policy.enabled OR p_amount>policy.per_transaction THEN RAISE EXCEPTION 'EXPLICIT_APPROVAL_REQUIRED'; END IF;

   IF policy.settle_first AND EXISTS(SELECT 1 FROM stock_funding.advances x WHERE x.organization_id=r.organization_id AND x.store_id=r.store_id AND x.responsible_id=r.responsible_id AND x.id<>r.id AND x.status IN ('FUNDED','PARTIALLY_RECONCILED')) THEN RAISE EXCEPTION 'OUTSTANDING_ADVANCE_BLOCKED'; END IF;

   IF coalesce((SELECT sum(-m.delta) FROM funding_control.movements m WHERE m.account=ac.id AND m.actor=a AND m.business_day=day AND m.auto_approved AND m.kind='FUND'),0)+p_amount>policy.per_day THEN RAISE EXCEPTION 'DAILY_LIMIT_EXCEEDED'; END IF;

   automatic:=true;

  END IF;

  delta:=-p_amount;

 ELSIF p_kind='RETURN' THEN

  IF r.status NOT IN ('FUNDED','PARTIALLY_RECONCILED') OR p_amount>r.amount-r.spent-greatest(r.returned,coalesce((SELECT sum(m.delta) FROM funding_control.movements m WHERE m.advance=r.id AND m.kind='RETURN'),0)) THEN RAISE EXCEPTION 'OVER_RECONCILIATION'; END IF;

  delta:=p_amount;

 ELSE

  IF r.status<>'FUNDED' OR r.spent<>0 OR r.returned<>0 OR EXISTS(SELECT 1 FROM funding_control.movements m WHERE m.advance=r.id AND m.kind IN ('RETURN','REVERSE')) OR p_amount<>r.amount OR p_account<>r.source_account THEN RAISE EXCEPTION 'CONTROLLED_REVERSAL_REQUIRED'; END IF;

  delta:=p_amount;

 END IF;

 balance:=ac.opening+coalesce((SELECT sum(m.delta) FROM funding_control.movements m WHERE m.account=ac.id),0);

 IF balance+delta<0 THEN RAISE EXCEPTION 'INSUFFICIENT_FUNDS'; END IF;

 INSERT INTO funding_control.movements(account,advance,request,actor,delta,kind,business_day,auto_approved,shift_id) VALUES(ac.id,r.id,p_request,a,delta,p_kind,day,automatic,v_shift);

END $function$

CREATE OR REPLACE FUNCTION funding_canonical.custody_read(o uuid, s uuid, person uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE a uuid:=auth.uid();role text;result jsonb;

BEGIN

 role:=funding_canonical.scope_role(a,o,s);

 IF role IS NULL OR (role NOT IN ('owner','admin') AND a<>person) OR funding_canonical.scope_role(person,o,s) IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 IF NOT EXISTS(SELECT 1 FROM public.stores WHERE id=s AND organization_id=o AND store_type='FIELD_PROCUREMENT') THEN RAISE EXCEPTION 'NOT_FIELD_PROCUREMENT'; END IF;

 SELECT jsonb_agg(jsonb_build_object('walletId',w.id,'membershipId',m.id,'responsibleId',m.user_id,'balance',w.balance::text,'currency',NULL,'currencyVerified',false,'history',coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'type',t.type,'purpose',t.purpose,'amount',t.amount::text,'balanceBefore',t.balance_before::text,'balanceAfter',t.balance_after::text,'createdAt',t.created_at,'itemName',t.item_name,'quantity',t.quantity::text,'currency',NULL,'currencyVerified',false) ORDER BY t.created_at,t.id) FROM public.field_wallet_transactions t WHERE t.wallet_id=w.id AND t.organization_id=o AND t.store_id=s AND t.membership_id=m.id),'[]'::jsonb))) INTO result

 FROM public.field_wallets w JOIN public.org_memberships m ON m.id=w.membership_id

 WHERE w.organization_id=o AND w.store_id=s AND w.is_active IS TRUE AND m.organization_id=o AND m.user_id=person AND m.is_active IS TRUE;

 RETURN coalesce(result,'[]'::jsonb);

END $function$

CREATE OR REPLACE FUNCTION funding_canonical.receipt_capability(o uuid, s uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE kind text;

BEGIN

 IF funding_canonical.scope_role(auth.uid(),o,s) IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 SELECT store_type INTO kind FROM public.stores WHERE id=s AND organization_id=o;

 RETURN jsonb_build_object('storeType',kind,'settlementAllowed',false,'code',CASE WHEN kind IN ('STANDARD','PRECISION_RETAIL','FIELD_PROCUREMENT') THEN 'CANONICAL_RECEIPT_ATTESTATION_REQUIRED' ELSE 'UNSUPPORTED_STOCK_WORKFLOW' END);

END $function$

CREATE OR REPLACE FUNCTION funding_canonical.command(o uuid, s uuid, req uuid, adv uuid, op text, body jsonb, revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE a uuid:=auth.uid();r stock_funding.advances%ROWTYPE;ac funding_control.accounts%ROWTYPE;cached funding_canonical.requests%ROWTYPE;

 envelope jsonb;result jsonb;core_request uuid;core_revision integer:=revision;operation_permission text;account_id uuid;

BEGIN

 IF a IS NULL OR o IS NULL OR s IS NULL OR req IS NULL OR adv IS NULL OR body IS NULL OR jsonb_typeof(body)<>'object' OR funding_canonical.scope_role(a,o,s) IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 IF op IS NULL OR op NOT IN ('CREATE','APPROVE','FUND','RECEIPT','RETURN','CANCEL','REVERSE') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 PERFORM pg_advisory_xact_lock(hashtextextended(o::text||req::text,0));

 envelope:=jsonb_build_object('store',s,'advance',adv,'action',op,'body',body,'revision',revision);

 SELECT * INTO cached FROM funding_canonical.requests WHERE org=o AND request=req;

 IF FOUND THEN IF cached.actor<>a OR cached.envelope<>envelope THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF;RETURN cached.result;END IF;

 IF op='CREATE' THEN account_id:=(body->>'sourceAccountId')::uuid;

 ELSE

  SELECT * INTO r FROM stock_funding.advances WHERE id=adv FOR UPDATE;

  IF NOT FOUND OR r.organization_id<>o OR r.store_id<>s THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  IF r.revision IS DISTINCT FROM revision THEN RAISE EXCEPTION 'STALE_REVISION'; END IF;

  account_id:=CASE WHEN op='RETURN' THEN (body->>'destinationAccountId')::uuid ELSE r.source_account END;

 END IF;

 SELECT * INTO ac FROM funding_control.accounts WHERE id=account_id;

 IF NOT FOUND OR ac.org<>o OR ac.store<>s THEN RAISE EXCEPTION 'ACCOUNT_FORBIDDEN_OR_LOCKED'; END IF;

 operation_permission:=CASE op WHEN 'CREATE' THEN 'REQUEST' WHEN 'CANCEL' THEN 'REQUEST' WHEN 'APPROVE' THEN 'APPROVE' WHEN 'RETURN' THEN 'RETURN' ELSE 'RELEASE' END;

 IF funding_control.can(a,o,s,ac.id,operation_permission) IS NOT TRUE THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 IF op='CANCEL' AND a<>r.created_by AND funding_canonical.scope_role(a,o,s)<>'owner' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 IF op='APPROVE' THEN PERFORM funding_control.approve(adv,revision); END IF;

 -- Original request remains the outer replay identity; private subcommands have stable distinct IDs.

 core_request:=md5(o::text||req::text||':CORE')::uuid;

 IF op='FUND' AND r.status='DRAFT' THEN

  PERFORM stock_funding.command(o,s,md5(o::text||req::text||':AUTO_APPROVE')::uuid,adv,'APPROVE',body,revision);

  core_revision:=revision+1;

 END IF;

 PERFORM set_config('funding_canonical.request',req::text,true);

 result:=stock_funding.command(o,s,core_request,adv,op,body,core_revision);

 IF op='APPROVE' THEN UPDATE funding_control.approvals SET record_revision=(result->>'revision')::integer WHERE advance=adv AND approved_by=a; END IF;

 INSERT INTO funding_canonical.requests VALUES(o,req,a,envelope,result);

 RETURN result;

END $function$

CREATE OR REPLACE FUNCTION funding_canonical.cashier_reconciliation(shift uuid, from_time timestamp with time zone, to_time timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE cs public.cashier_shifts%ROWTYPE;pay record;delta numeric;units integer;funding_currency text;

BEGIN

 SELECT * INTO cs FROM public.cashier_shifts WHERE id=shift;

 IF NOT FOUND OR funding_canonical.scope_role(auth.uid(),cs.organization_id,cs.store_id) IS DISTINCT FROM 'cashier' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 -- Actual captured RPC enforces same cashier membership and strict shift window.

 SELECT * INTO pay FROM public.get_my_cashier_closing_payment_summary_v1(shift,from_time,to_time);

 SELECT count(DISTINCT ac.currency),coalesce(sum(m.delta),0),min(ac.currency) INTO units,delta,funding_currency FROM funding_control.movements m JOIN funding_control.accounts ac ON ac.id=m.account WHERE m.shift_id=shift;

 IF units>1 THEN RAISE EXCEPTION 'CROSS_CURRENCY_BLOCKED'; END IF;

 RETURN jsonb_build_object('shiftId',shift,'opening',cs.opening_cash::text,'canonicalCashReceived',pay.v_cash_total::text,'fundingMovementDelta',delta::text,'baselineExpected',(cs.opening_cash+pay.v_cash_total)::text,'expectedWithFunding',NULL,'fundingCurrency',funding_currency,'baselineCurrencyVerified',false,'integrationStatus','BLOCKED_SHIFT_CURRENCY_CONTEXT','scope','CANONICAL_BASELINE_PLUS_FUNDING_ONLY','sourceBalanceVerified',false);

END $function$

CREATE OR REPLACE FUNCTION funding_evidence.attest(movement uuid, writer_name text, request uuid, source_line uuid, event uuid, code text, rev integer, cost numeric, cost_proof text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE m public.stock_movements%ROWTYPE;ctx jsonb;prior funding_evidence.receipts%ROWTYPE;

BEGIN

 IF funding_evidence.writer_bound(writer_name) IS NOT TRUE THEN RAISE EXCEPTION 'RECEIPT_WRITER_NOT_BOUND'; END IF;

 SELECT * INTO m FROM public.stock_movements WHERE id=movement FOR UPDATE;

 IF NOT FOUND OR m.mode<>'ADD' OR m.amount<=0 OR m.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'INVALID_RECEIPT_MOVEMENT'; END IF;

 IF funding_canonical.scope_role(auth.uid(),m.organization_id,m.store_id) IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 ctx:=stock_funding.currency_context(m.organization_id);

 IF ctx IS NULL OR ctx->>'currency' IS DISTINCT FROM code OR (ctx->>'revision')::integer IS DISTINCT FROM rev THEN RAISE EXCEPTION 'CURRENCY_CONTEXT_CHANGED'; END IF;

 SELECT * INTO prior FROM funding_evidence.receipts WHERE movement_id=movement;

 IF FOUND THEN

  IF prior.writer=writer_name AND prior.request_id=request AND prior.source_line_id=source_line AND prior.event_id=event AND prior.transaction_currency=code AND prior.currency_revision=rev AND prior.unit_cost=cost AND prior.cost_evidence=cost_proof AND prior.quantity=m.amount AND prior.product_id=m.product_id AND prior.organization_id=m.organization_id AND prior.store_id=m.store_id THEN RETURN; END IF;

  RAISE EXCEPTION 'ATTESTATION_CONFLICT';

 END IF;

 IF NOT EXISTS(SELECT 1 FROM public.stock_movements x WHERE x.id=movement AND x.xmin=pg_current_xact_id()::text::xid) THEN RAISE EXCEPTION 'RECEIPT_NOT_SAME_TRANSACTION'; END IF;

 IF m.event_id IS NOT NULL AND m.event_id IS DISTINCT FROM event THEN RAISE EXCEPTION 'EVENT_MISMATCH'; END IF;

 INSERT INTO funding_evidence.receipts(movement_id,organization_id,store_id,product_id,writer,request_id,event_id,source_line_id,transaction_currency,accounting_currency,currency_revision,quantity,unit_cost,recognized_cost,cost_method,cost_evidence,actor_id)

 VALUES(m.id,m.organization_id,m.store_id,m.product_id,writer_name,request,event,source_line,code,code,rev,m.amount,cost,m.amount*cost,'CANONICAL_SNAPSHOT',cost_proof,auth.uid());

END $function$

CREATE OR REPLACE FUNCTION funding_evidence.confirm_wallet_units(wallet uuid, code text, rev integer, proof text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE w public.field_wallets%ROWTYPE;ctx jsonb;prior funding_evidence.wallet_units%ROWTYPE;

BEGIN

 SELECT * INTO w FROM public.field_wallets WHERE id=wallet FOR UPDATE;

 IF NOT FOUND OR NOT w.is_active OR funding_canonical.scope_role(auth.uid(),w.organization_id,w.store_id) IS DISTINCT FROM 'owner' THEN RAISE EXCEPTION 'OWNER_REQUIRED'; END IF;

 IF funding_evidence.wallet_writers_bound(wallet) IS NOT TRUE THEN RAISE EXCEPTION 'WALLET_WRITERS_NOT_BOUND'; END IF;

 ctx:=stock_funding.currency_context(w.organization_id);

 IF ctx IS NULL OR ctx->>'currency' IS DISTINCT FROM code OR (ctx->>'revision')::integer IS DISTINCT FROM rev THEN RAISE EXCEPTION 'CURRENCY_CONTEXT_CHANGED'; END IF;

 SELECT * INTO prior FROM funding_evidence.wallet_units WHERE wallet_id=wallet;

 IF FOUND THEN

  IF prior.currency=code AND prior.currency_revision=rev AND prior.evidence=proof AND prior.confirmed_by=auth.uid() AND prior.organization_id=w.organization_id AND prior.store_id=w.store_id AND prior.membership_id=w.membership_id THEN RETURN; END IF;

  RAISE EXCEPTION 'CONTROLLED_CURRENCY_CHANGE_REQUIRED';

 END IF;

 INSERT INTO funding_evidence.wallet_units(wallet_id,organization_id,store_id,membership_id,currency,currency_revision,cutover_balance,history_count,confirmed_by,evidence)

 SELECT w.id,w.organization_id,w.store_id,w.membership_id,code,rev,w.balance,count(*),auth.uid(),proof FROM public.field_wallet_transactions WHERE wallet_id=w.id;

END $function$

CREATE OR REPLACE FUNCTION funding_evidence.return_intent(advance uuid, wallet uuid, destination uuid, amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$

DECLARE a stock_funding.advances%ROWTYPE;w public.field_wallets%ROWTYPE;u funding_evidence.wallet_units%ROWTYPE;ac funding_control.accounts%ROWTYPE;ctx jsonb;

BEGIN

 SELECT * INTO a FROM stock_funding.advances WHERE id=advance FOR UPDATE;

 IF NOT FOUND OR funding_canonical.scope_role(auth.uid(),a.organization_id,a.store_id) IS NULL THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

 SELECT * INTO ac FROM funding_control.accounts WHERE id=destination FOR UPDATE;

 IF NOT FOUND OR ac.org<>a.organization_id OR ac.store<>a.store_id OR ac.locked OR funding_control.can(auth.uid(),a.organization_id,a.store_id,destination,'RETURN') IS NOT TRUE THEN RAISE EXCEPTION 'RETURN_ACCOUNT_FORBIDDEN'; END IF;

 -- Match canonical posting lock order: advance -> account -> shift -> wallet.

 IF ac.kind='CASH' THEN PERFORM funding_control.require_open_shift(auth.uid(),a.organization_id,a.store_id); END IF;

 SELECT * INTO w FROM public.field_wallets WHERE id=wallet FOR UPDATE;

 IF NOT FOUND OR NOT w.is_active OR w.organization_id<>a.organization_id OR w.store_id<>a.store_id THEN RAISE EXCEPTION 'CUSTODY_SCOPE_MISMATCH'; END IF;

 IF NOT EXISTS(SELECT 1 FROM public.org_memberships m JOIN public.org_membership_stores ms ON ms.membership_id=m.id WHERE m.id=w.membership_id AND m.organization_id=a.organization_id AND m.user_id=a.responsible_id AND m.is_active AND ms.store_id=a.store_id) THEN RAISE EXCEPTION 'CUSTODIAN_NOT_ACTIVE'; END IF;

 IF NOT EXISTS(SELECT 1 FROM public.stores WHERE id=a.store_id AND store_type='FIELD_PROCUREMENT' AND is_active) THEN RAISE EXCEPTION 'FIELD_STORE_REQUIRED'; END IF;

 IF NOT EXISTS(

  SELECT 1 FROM funding_evidence.custody_links l

  JOIN funding_control.movements fm ON fm.id=l.movement_id

  JOIN public.field_wallet_transactions wt ON wt.id=l.wallet_transaction_id

  WHERE l.advance_id=a.id AND l.kind='FUND' AND fm.advance=a.id AND fm.kind='FUND'

   AND fm.account=a.source_account AND fm.delta=-a.amount AND wt.wallet_id=w.id

   AND wt.organization_id=a.organization_id AND wt.store_id=a.store_id

   AND wt.membership_id=w.membership_id AND wt.type='ALLOCATE' AND wt.amount=a.amount

   AND wt.balance_after-wt.balance_before=wt.amount

 ) THEN RAISE EXCEPTION 'FUNDED_CUSTODY_LINK_REQUIRED'; END IF;

 SELECT * INTO u FROM funding_evidence.wallet_units WHERE wallet_id=wallet;

 IF NOT FOUND OR funding_evidence.wallet_writers_bound(wallet) IS NOT TRUE THEN RAISE EXCEPTION 'CUSTODY_CURRENCY_UNCONFIRMED'; END IF;

 ctx:=stock_funding.currency_context(a.organization_id);

 IF ctx IS NULL OR ctx->>'currency' IS DISTINCT FROM a.currency OR (ctx->>'revision')::integer IS DISTINCT FROM a.currency_revision OR ac.currency<>a.currency OR u.currency<>a.currency OR u.currency_revision<>a.currency_revision OR u.organization_id<>w.organization_id OR u.store_id<>w.store_id OR u.membership_id<>w.membership_id THEN RAISE EXCEPTION 'CROSS_CURRENCY_OR_STALE_CONTEXT'; END IF;

 IF amount IS NULL OR NOT(amount>0 AND amount<1e24) OR amount<>round(amount,a.minor_units) OR amount>a.amount-a.spent-a.returned OR amount>w.balance OR a.status NOT IN ('FUNDED','PARTIALLY_RECONCILED') THEN RAISE EXCEPTION 'INVALID_RETURN_AMOUNT_OR_STATE'; END IF;

 RETURN jsonb_build_object('advanceId',a.id,'walletId',w.id,'destinationAccountId',ac.id,'amount',amount::text,'transactionCurrency',a.currency,'accountingCurrency',a.currency,'rate','1','financialPostingActivated',false,'requiredContract','CANONICAL_RETURN_AND_OPEN_CYCLE_BINDING');

END $function$

CREATE OR REPLACE FUNCTION public.block_inventory_movements_when_day_locked()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    DECLARE
      v_date date;
      v_locked boolean;
    BEGIN
      -- use TZ date for Tanzania
      v_date := (NEW.created_at AT TIME ZONE 'Africa/Dar_es_Salaam')::date;

      SELECT public.is_closing_locked(NEW.store_id, v_date) INTO v_locked;

      IF v_locked THEN
        RAISE EXCEPTION 'Day is locked (%). No inventory movements allowed.', v_date;
      END IF;

      RETURN NEW;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.guard_inventory_movements_if_locked()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_store_id uuid;
  v_date_text text;
  v_date date;
begin
  -- expect store_id to exist
  v_store_id := (to_jsonb(new)->>'store_id')::uuid;

  -- try movement_date first, else created_at, else current_date
  v_date_text := coalesce(
    to_jsonb(new)->>'movement_date',
    left(to_jsonb(new)->>'created_at', 10)
  );

  if v_date_text is null or v_date_text = '' then
    v_date := current_date;
  else
    v_date := v_date_text::date;
  end if;

  if public.is_closing_locked(v_store_id, v_date) then
    raise exception 'This day is locked (%). No movements allowed.', v_date;
  end if;

  return new;
end;
$function$
